    public String fixSpaces(String text) {
        StringBuilder newText = new StringBuilder();
        int i = 0;
        int start = 0, end = 0;
        while (i < text.length()) {
            if (text.charAt(i) == ' ') {
                end++;
            } else {
                if (end - start > 2) {
                    newText.append("-").append(text.charAt(i));
                } else if (end - start > 0) {
                    newText.append("_".repeat(Math.max(0, end - start)));
                    newText.append(text.charAt(i));
                } else {
                    newText.append(text.charAt(i));
                }
                start = end = i + 1;
            }
            i++;
        }
        if (end - start > 2) {
            newText.append("-");
        } else if (end - start > 0) {
            newText.append("_".repeat(Math.max(0, end - start)));
        }
        return newText.toString();
    }
